from datetime import datetime, timedelta


class ParkingMeter:
    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = hourly_rate
        self._fees = []

    def fee(self, entry: datetime, exit: datetime) -> float:
        duration = exit - entry

        if duration < timedelta(0):
            raise ValueError("Exit time cannot be earlier than entry time")
        if duration <= timedelta(minutes=15):
            return 0.0
        if duration > timedelta(hours=24):
            return 200.0

        hours, remainder = divmod(duration, timedelta(hours=1))
        if remainder:
            hours += 1
        return round(hours * self.hourly_rate, 2)

    def estimate(self, hours: int) -> float:
        entry = datetime(2000, 1, 1)
        return self.fee(entry, entry + timedelta(hours=hours))

    def record(self, entry: datetime, exit: datetime) -> float:
        amount = self.fee(entry, exit)
        self._fees.append(amount)
        return amount

    def total_collected(self) -> float:
        return round(sum(self._fees), 2)
```

